<?php
$titulo_pagina='Perfil profissional';$estilos_pagina=['/assets/css/marketplace.css?v=2','/assets/css/chat-contact.css?v=1','/assets/css/profile-services.css?v=1'];$scripts_pagina=['/assets/js/profile-services.js?v=1'];require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';
$perfil=pegar_perfil_profissional((int)($_GET['id']??0));if(!$perfil){http_response_code(404);$titulo_pagina='Profissional não encontrado';}
if($perfil&&usuario_autenticado()&&(int)$_SESSION['usuario_id']!==(int)$perfil['usuario_id']){$visitante=(int)$_SESSION['usuario_id'];$stmt=$mysqli->prepare('INSERT INTO visitas_perfis(profissional_id,visitante_id) VALUES(?,?)');$stmt->bind_param('ii',$perfil['id'],$visitante);$stmt->execute();}
$ofertas=[];if($perfil){$stmt=$mysqli->prepare('SELECT * FROM ofertas_profissionais WHERE profissional_id=? AND ativo=1 ORDER BY criado_em DESC');$stmt->bind_param('i',$perfil['id']);$stmt->execute();$ofertas=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$telefone_profissional=preg_replace('/\D/','',$perfil['telefone']);if($telefone_profissional&&!str_starts_with($telefone_profissional,'55'))$telefone_profissional='55'.$telefone_profissional;if(!usuario_autenticado())$telefone_profissional='';}
require_once __DIR__.'/includes/header.php';
?>
<section class="market-page"><div class="container"><?php if(!$perfil): ?><div class="market-empty"><h1>Profissional não encontrado</h1><a class="btn" href="/profissionais.php">Voltar à busca</a></div><?php else: ?><div class="public-profile"><aside><div class="professional-avatar profile-avatar"><?php if($perfil['foto_url']): ?><img src="<?php echo sanitizar($perfil['foto_url']); ?>" alt="Foto de <?php echo sanitizar($perfil['nome']); ?>"><?php else: echo sanitizar(mb_strtoupper(mb_substr($perfil['nome'],0,1)));endif; ?></div><h1><?php echo sanitizar($perfil['nome']); ?> <?php if($perfil['verificado']): ?><span class="verified">✓</span><?php endif; ?></h1><?php if($perfil['mei']&&$perfil['marca']): ?><div class="business-badge"><?php echo sanitizar($perfil['marca']); ?> <strong>(MEI)</strong></div><?php endif; ?><h2><?php echo sanitizar($perfil['titulo_profissional']); ?></h2><div class="professional-tags"><span><?php echo sanitizar($perfil['categoria_principal']); ?></span><span>⌖ <?php echo sanitizar($perfil['cidade'].'/'.$perfil['uf']); ?></span><?php if($perfil['atende_online']): ?><span>Atende online</span><?php endif; ?></div><p><?php echo nl2br(sanitizar($perfil['bio'])); ?></p><?php if(usuario_autenticado()): ?><a class="contact-professional" href="https://wa.me/<?php echo $telefone_profissional; ?>?text=<?php echo rawurlencode('Olá '.$perfil['nome'].'! Encontrei seu perfil na VoltX.'); ?>" target="_blank" rel="noopener noreferrer">◉ Conversar no WhatsApp</a><?php else: ?><a class="contact-professional" href="/login.php?redirect=<?php echo rawurlencode('/profissional.php?id='.(int)$perfil['id']); ?>">Entrar para ver o contato</a><?php endif; ?></aside><main><span class="profile-kicker">SERVIÇOS OFERECIDOS</span><h2>Escolha uma solução</h2><?php if($ofertas): ?><div class="offers-list"><?php foreach($ofertas as $oferta): ?><article><?php if($oferta['imagem_url']): ?><img class="offer-thumb" src="<?php echo sanitizar($oferta['imagem_url']); ?>" alt=""><?php endif; ?><div><span><?php echo sanitizar($oferta['categoria']); ?></span><h3><?php echo sanitizar($oferta['nome']); ?></h3><p><?php echo nl2br(sanitizar($oferta['descricao'])); ?></p><b>★ <?php echo number_format((float)$oferta['nota_media'],1,',','.'); ?>/10 · <?php echo (int)$oferta['total_avaliacoes']; ?> avaliações</b></div><strong>R$ <?php echo number_format((float)$oferta['preco_inicial'],2,',','.'); ?><small><?php echo sanitizar($oferta['unidade_preco']); ?></small></strong></article><?php endforeach; ?></div><?php else: ?><p>Este profissional ainda não publicou serviços.</p><?php endif; ?></main></div><?php endif; ?></div></section><?php require_once __DIR__.'/includes/footer.php'; ?>
